fn main() {
let pencils = 3;
println!("{}", pencils + 2);
}

fn main() {
let mut score = 3;
score += 2;
println!("{}", score);
}

fn main() {
let score = 8;
let message = if score >= 5 { "Pass" } else { "Try again" };
println!("{}", message);
}

fn main() {
for n in 1..=3 { println!("{}", n); }
}

fn main() {
let mut scores = vec![4, 5];
scores.push(8);
println!("{:?}", scores);
}

fn main() {
let first = String::from("Asha");
let second = first;
println!("{}", second);
}

fn main() {
let name = String::from("Asha");
let borrowed = &name;
println!("{} {}", borrowed, name);
}

fn main() {
let score: Option<i32> = None;
println!("{}", score.unwrap_or(0));
}

fn main() {
match "cat".parse::<i32>() {
 Ok(n) => println!("{}", n),
 Err(_) => println!("Use a number"),
}
}

fn main() {
struct Book { title: String }
let book = Book { title: String::from("Moon Trip") };
println!("{}", book.title);
}
